write('avl-tree',
 "An AVL tree is a binary search tree that keeps itself balanced: for every node the heights of its left and right subtrees differ by at most one. Rotations after inserts and deletes restore the invariant, guaranteeing O(log n) search, insert, and delete.",
 [S('Balance factor', "balance(node) = height(left) - height(right). In an AVL tree every node has balance -1, 0, or +1. Each node stores its height so balance is O(1) to compute. An AVL tree of n nodes has height at most about 1.44 log2(n).", code="int height(Node *n) { return n ? n->h : 0; }\nint balance(Node *n) { return n ? height(n->left) - height(n->right) : 0; }\nvoid update(Node *n) { n->h = 1 + max(height(n->left), height(n->right)); }"),
  S('Rotations', "A rotation is a local pointer rearrangement that changes heights but preserves BST order.", code="Node *rotate_right(Node *y) {      //     y          x\n  Node *x = y->left;               //    / \\        / \\\n  y->left = x->right;              //   x   C  ->  A   y\n  x->right = y;                    //  / \\            / \\\n  update(y); update(x); return x;  // A   B          B   C\n}\nNode *rotate_left(Node *x) {\n  Node *y = x->right;\n  x->right = y->left; y->left = x;\n  update(x); update(y); return y;\n}"),
  S('The four imbalance cases', "After inserting, walk back up. At the first node z with |balance| = 2:", bullets=["Left-Left (balance > 1, new key in left child's left): rotate right at z.", "Right-Right (balance < -1, key in right child's right): rotate left at z.", "Left-Right (balance > 1, key in left child's right): rotate left at the left child, then right at z.", "Right-Left (balance < -1, key in right child's left): rotate right at the right child, then left at z."]),
  S('Insertion', "Insert as in a normal BST, then recompute heights on the way back up and rebalance.", code="Node *insert(Node *n, int k) {\n  if (!n) return new_node(k);\n  if (k < n->key) n->left = insert(n->left, k);\n  else if (k > n->key) n->right = insert(n->right, k);\n  else return n;\n  update(n);\n  int b = balance(n);\n  if (b > 1 && k < n->left->key)  return rotate_right(n);\n  if (b < -1 && k > n->right->key) return rotate_left(n);\n  if (b > 1 && k > n->left->key)  { n->left = rotate_left(n->left); return rotate_right(n); }\n  if (b < -1 && k < n->right->key) { n->right = rotate_right(n->right); return rotate_left(n); }\n  return n;\n}"),
  S('Complexity', None, bullets=["Search, insert, delete: O(log n) worst case.", "An insertion needs at most one single or double rotation.", "A deletion may need O(log n) rotations along the path.", "Space: O(n), plus a height field per node."])],
 [SUB('Deletion', 'Same cases, possibly many times.', S(None, "Delete like a BST (replace a two-child node by its in-order successor), then rebalance every ancestor on the way up. Unlike insertion, one fix may not be enough because the subtree height can shrink and propagate upward.")),
  SUB('AVL versus red-black trees', 'Which is better?', S(None, bullets=["AVL is more strictly balanced: faster lookups, slower inserts/deletes (more rotations).", "Red-black trees allow a looser height (up to 2 log n) with fewer rotations; used in std::map, TreeMap, and the Linux scheduler.", "Choose AVL for read-heavy workloads, red-black for write-heavy ones."])),
  SUB('Building from sorted input', 'The motivation.', S(None, "A plain BST fed 1, 2, 3, ... becomes a linked list with O(n) operations. An AVL tree rotates at each step and stays near log n height, so sorted input is safe.")),
  SUB('Verifying an AVL tree', 'Tests worth writing.', S(None, "Check three invariants after each operation: BST ordering via inorder traversal, stored heights equal the recomputed heights, and every balance factor lies in [-1, 1].")),
  SUB('Applications', 'Where balance matters.', S(None, bullets=["In-memory ordered indexes and dictionaries.", "Real-time systems needing predictable lookup time.", "Order statistics when augmented with subtree sizes.", "Interval and range queries when augmented."]))],
 ["Balance factor must stay in {-1, 0, +1} at every node.", "Fix imbalance with single (LL, RR) or double (LR, RL) rotations.", "Guarantees O(log n) search, insert, delete.", "More strictly balanced than red-black trees: faster reads, costlier updates."],
 [CLRS, SED, GFG('AVL tree', 'https://www.geeksforgeeks.org/introduction-to-avl-tree/')],
 P(('Insert keys 10 20 30 40 50 25 and draw the tree after each step', E), ('Implement LL and RR rotations', M), ('Implement full AVL insertion with all four cases', M), ('Implement AVL deletion', H), ('Check whether a binary tree is height-balanced', E)))

write('trie',
 "A trie (prefix tree) stores strings along root-to-node paths, one character per edge. Inserting, searching, and prefix-searching a string of length L all take O(L) time regardless of how many strings are stored, which makes tries ideal for autocomplete and dictionaries.",
 [S('Structure', "Each node has links to children (an array of 26 for lowercase letters, or a map for larger alphabets) and a flag marking that a word ends here. The root represents the empty prefix.", code="typedef struct TrieNode {\n  struct TrieNode *child[26];\n  int is_end;\n} TrieNode;\n\nTrieNode *node_new(void) { return calloc(1, sizeof(TrieNode)); }"),
  S('Insert and search', "Walk the characters, creating missing nodes on insert. Search succeeds only if the walk completes and the final node's end flag is set.", code="void insert(TrieNode *root, const char *w) {\n  for (; *w; w++) {\n    int c = *w - 'a';\n    if (!root->child[c]) root->child[c] = node_new();\n    root = root->child[c];\n  }\n  root->is_end = 1;\n}\nint search(TrieNode *root, const char *w) {\n  for (; *w; w++) { root = root->child[*w - 'a']; if (!root) return 0; }\n  return root->is_end;\n}"),
  S('Prefix queries', "To test whether any word starts with a prefix, walk the prefix and succeed if all nodes exist (ignore the end flag). To autocomplete, walk the prefix, then depth-first collect every word below that node."),
  S('Complexity', None, bullets=["Insert, search, prefix check: O(L) where L is the string length, independent of the number of words.", "Space: O(total characters × alphabet size) in the array form; can be large.", "No hashing or collision handling needed; keys come out in lexicographic order."])],
 [SUB('Deletion', 'Prune unused branches.', S(None, "Unmark the end flag, then walk back up freeing nodes that have no children and are not the end of another word. Recursion makes this natural.")),
  SUB('Reducing memory', 'Compressed tries and maps.', S(None, bullets=["Store children in a hash map or sorted list instead of a fixed array.", "Compressed (radix/Patricia) trie: merge chains of single-child nodes into one edge labelled with a substring.", "Ternary search tries: three-way BST nodes per character, compact and still prefix-friendly."])),
  SUB('Applications', 'Where tries are used.', S(None, bullets=["Autocomplete and typeahead.", "Spell checkers and dictionary lookups.", "IP routing tables: a binary trie over address bits implements longest-prefix match.", "T9 text prediction and word games.", "Longest common prefix of many strings."])),
  SUB('Trie versus hash table', 'Trade-offs.', S(None, bullets=["Trie supports prefix search and sorted iteration; hash tables do not.", "Hash tables use less memory and have better constants for exact lookups.", "Trie lookup time depends on key length, not table size."])),
  SUB('Binary tries for numbers', 'Bitwise tries.', S(None, "Store integers bit by bit to answer queries like 'maximum XOR with any stored number' in O(bits): at each bit choose the child that gives the opposite bit when possible."))],
 ["Paths from the root spell strings; a flag marks word ends.", "Insert, search, and prefix queries are O(L).", "Great for autocomplete and longest-prefix problems; memory can be large.", "Compressed tries cut memory by merging single-child chains."],
 [CLRS, SED, GFG('Trie data structure', 'https://www.geeksforgeeks.org/trie-insert-and-search/')],
 P(('Implement insert, search, and startsWith', E), ('Autocomplete: list all words with a given prefix', M), ('Longest common prefix of an array of strings', E), ('Word search II: find dictionary words in a grid', H), ('Maximum XOR of two numbers using a binary trie', H)))
